control verify_checksum(inout headers hdr, inout metadata meta) {
    apply {
        if (hdr.ip.version != 4) {
            // Not IPv4 packet
            return;
        }
        if (hdr.ip.header_length != 5) {
            // Invalid header length
            return;
        }
        if (hdr.ip.total_length < 20) {
            // Too short to be an IPv4 packet
            return;
        }
        if (hdr.ip.fragment_offset != 0) {
            // Fragmented packets are not supported
            return;
        }
        if (hdr.ip.ttl == 0) {
            // Packet has expired
            return;
        }
        if (!verify_ipv4_checksum(hdr.ip)) {
            // Checksum verification failed
            return;
        }
        hdr.ip.ttl = hdr.ip.ttl - 1;
        update_ipv4_checksum(hdr.ip);
    }
}

control forward_packet(inout headers hdr, inout metadata meta) {
    apply {
        if (hdr.ip.dstAddr == ingress.port) {
            // Dropping the packet if it's destined for the ingress port
            return;
        }
        // Forwarding the packet to the destination MAC address
        egress.setValid();
        egress.setPort(hdr.eth.dstAddr);
    }
}

function bit<16> compute_ipv4_checksum(ipv4_t ip) {
    uint16_t sum = 0;
    sum += ip.version << 8 | ip.ihl << 4 | ip.dscp << 2 | ip.ecn;
    sum += ip.total_length;
    sum += ip.identification;
    sum += ip.flags << 13 | ip.fragment_offset;
    sum += ip.ttl << 8 | ip.protocol;
    sum += ip.srcAddr[0] << 24 | ip.srcAddr[1] << 16 | ip.srcAddr[2] << 8 | ip.srcAddr[3];
    sum += ip.dstAddr[0] << 24 | ip.dstAddr[1] << 16 | ip.dstAddr[2] << 8 | ip.dstAddr[3];
    while (sum >> 16) {
        sum = (sum & 0xFFFF) + (sum >> 16);
    }
    return ~sum & 0xFFFF;
}

function void update_ipv4_checksum(inout ipv4_t ip) {
    ip.checksum = compute_ipv4_checksum(ip);
}

function bool verify_ipv4_checksum(ipv4_t ip) {
    return compute_ipv4_checksum(ip) == 0;
}

