control verify_checksum(inout headers_t h, inout metadata_t meta) {
    apply {
        if (h.ipv4.hdrChecksum != computeChecksum(h.ipv4)) {
            meta.checksum = 0;
        } else {
            meta.checksum = 1;
        }
    }
}

function computeChecksum(IPv4 ip) : bit<16> {
    // Pseudo header fields
    bit<32> sourceIP = ip.srcAddr;
    bit<32> destinationIP = ip.dstAddr;
    bit<8> zero = 0;
    bit<8> protocol = ip.protocol;
    bit<16> length = ip.totalLen;

    // Header fields
    bit<16> pseudoChecksum = 0;
    bit<16> checksum = 0;
    bit<16> tempChecksum = 0;

    // Calculate pseudo header checksum
    pseudoChecksum += sourceIP[15:0];
    pseudoChecksum += destinationIP[15:0];
    pseudoChecksum += length;
    pseudoChecksum += protocol;

    // Add IP header fields to checksum
    checksum += pseudoChecksum[15:0];
    checksum += pseudoChecksum[31:16];
    checksum += ip.ihl * 4; // Internet Header Length
    checksum += ip.diffserv;
    checksum += ip.totalLen;
    checksum += ip.identification;
    checksum += ip.flags << 13 | ip.fragOffset;
    checksum += ip.ttl;
    checksum += ip.protocol;
    checksum += ip.hdrChecksum;
    checksum += ip.srcAddr[15:0];
    checksum += ip.srcAddr[31:16];
    checksum += ip.dstAddr[15:0];
    checksum += ip.dstAddr[31:16];

    // Fold the checksum to 16 bits
    while (checksum > 0xFFFF) {
        checksum = (checksum & 0xFFFF) + (checksum >> 16);
    }

    return ~checksum;
}

