    action ipv4_lookup {
        ipv4_lpm.apply();
    }

    table_entry t_invalid {
        actions = {
            ipv4_lookup;
            verify_checksum(h, meta);
        }
        priority = 0;
    }

    apply {
        if (meta.checksum == 0) {
            // Drop invalid packets
            mark_to_drop(standard_metadata);
        } else {
            // Process valid packets
            accept_packet(standard_metadata, h);
        }
    }
}

