#include <core.p4>
#include <v1model.p4>

const bit<9> default_port = 0x80; // Default port identifier

struct Metadata {
    bit<9> ingress_port;
}

table forward_table {
    key = {
        bit<9> dst_port;
    }
    actions = {
        send_to_controller;
        modify_dst_port(bit<9>);
    }
    size = 256;
}

control Ingress(inout Headers hdr, inout Metadata meta, inout standard_metadata_t stdmeta) {
    apply {
        if (stdmeta.ingress_port != default_port) {
            meta.ingress_port = stdmeta.ingress_port;
            forward_table.apply();
        } else {
            // Handle default case where no specific port is assigned
            // For simplicity, we can drop the packet or redirect it elsewhere
            // Here, we choose to drop the packet
            stdmeta.drop = true;
        }
    }
}

control Deparser(packet_out packet, in Headers hdr) {
    apply {
        packet.emit(hdr);
    }
}

V1Switch(Ingress(), Deparser()) main() {
}

